WITH valid_stores AS (SELECT * FROM stores WHERE region = 'West' AND UPPER(store_name) LIKE '%ALL%'), agg AS (SELECT CASE WHEN region IN ('East', 'South') THEN 'core' ELSE 'other' END AS region_group, city, COUNT(DISTINCT sqft) AS unique_regions FROM valid_stores GROUP BY CASE WHEN region IN ('East', 'South') THEN 'core' ELSE 'other' END, city) SELECT region_group, city, unique_regions FROM agg ORDER BY unique_regions;
